function localTtsConfigured() { try { return spawnSync('which', ['espeak-ng'], { encoding: 'utf8' }).status === 0; } catch { return false; } }
// Sangbik defaults (user-chosen, 2026-10-26): offline Whisper tiny for
// transcription, Google Translate for translation, Edge TTS for voice.
// Azure/OpenAI/Gemini remain available if explicitly selected, but are NOT
// the defaults. No key is needed for the three defaults.
const WHISPER_PYTHON = path.join(__dirname, '.venv/bin/python');
const WHISPER_SCRIPT = path.join(__dirname, 'whisper_local.py');
const WHISPER_MODEL_NAME = process.env.WHISPER_MODEL || 'tiny';
function whisperInstalled() { try { return fs.existsSync(WHISPER_PYTHON) && fs.existsSync(WHISPER_SCRIPT); } catch { return false; } }
function edgeTtsInstalled() { try { return spawnSync('python3', ['-m', 'edge_tts', '--help'], { encoding: 'utf8' }).status === 0; } catch { return false; } }
function defaultTtsProvider() { return 'edge-tts'; }
async function runWhisperCheck() {
  if (!whisperInstalled()) throw new Error('Offline Whisper is not installed on this server: the server .venv (faster-whisper) or whisper_local.py is missing. Reinstall: python3 -m venv server/.venv && server/.venv/bin/pip install faster-whisper, then restart the server.');
  const { out, err } = await run(WHISPER_PYTHON, [WHISPER_SCRIPT, '--check']);
  const line = (out || '').trim();
  if (!line.startsWith('MODEL_READY')) throw new Error(`Offline Whisper model did not load: ${line || err.slice(-500)}`);
  return line;
}
// FAST-progress: stream Whisper output line-by-line so each finished 60s
// segment updates the job percent (20% -> 70%) instead of sitting at 20%
// until every segment finishes. whisper_local.py already prints one JSON
// line per segment with flush=True.
function transcribeOfflineFilesStreaming(wavFiles, onSegment) {
  if (!whisperInstalled()) throw new Error('Offline Whisper is not installed on this server (server/.venv or whisper_local.py missing).');
  return new Promise((resolve, reject) => {
    const p = spawn(WHISPER_PYTHON, [WHISPER_SCRIPT, ...wavFiles]);
    let err = '', buf = '';
    const results = [];
    const handleLine = (line) => { const t = line.trim(); if (t.startsWith('{')) { try { results.push(JSON.parse(t)); if (onSegment) onSegment(results.length); } catch {} } };
    p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf(String.fromCharCode(10))) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); handleLine(line); } });
    p.stderr.on('data', d => err += d);
    p.on('error', reject);
    p.on('close', code => { if (buf.trim()) handleLine(buf); if (code !== 0) return reject(new Error('whisper_local.py exited ' + code + ': ' + err.slice(-2000))); if (!results.length) return reject(new Error('Offline Whisper produced no output: ' + (err || '').slice(-1000))); resolve(results); });
  });
}
async function transcribeOfflineFiles(wavFiles) {
  if (!whisperInstalled()) throw new Error('Offline Whisper is not installed on this server (server/.venv or whisper_local.py missing).');
  const { out, err } = await run(WHISPER_PYTHON, [WHISPER_SCRIPT, ...wavFiles]);
  const results = [];
  for (const line of (out || '').split('\n')) { const t = line.trim(); if (t.startsWith('{')) { try { results.push(JSON.parse(t)); } catch {} } }
  if (!results.length) throw new Error(`Offline Whisper produced no output: ${(err || '').slice(-1000)}`);
  return results;
}
// Google Translate (free endpoint, no key): batch translate. Returns the
// translated strings in the same order. Throws the exact HTTP error on
// failure (e.g. 429 rate-limit) — the caller logs it and tries the AI
// fallback, never inventing a translation.
async function googleTranslateBatch(texts, target = 'my', source = 'auto') {
  if (!texts.length) return [];
  const params = new URLSearchParams();
  params.append('client', 'gtx'); params.append('sl', source); params.append('tl', target); params.append('dt', 't');
  for (const t of texts) params.append('q', t);
  const url = 'https://translate.googleapis.com/translate_a/single?' + params.toString();
  const r = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
  const body = await r.text();
  if (!r.ok) throw new Error(`Google Translate HTTP ${r.status}: ${body.slice(0, 300)}`);
  let j; try { j = JSON.parse(body); } catch { throw new Error(`Google Translate returned unparseable output: ${body.slice(0, 300)}`); }
  const rows = j[0] || [];
  if (rows.length !== texts.length) throw new Error(`Google Translate returned ${rows.length} translations for ${texts.length} inputs.`);
  return rows.map(row => (Array.isArray(row) ? row.map(x => (typeof x === 'string' ? x : '')).join('') : '').trim());
}
// MyMemory free API (no key). MUST reject its quota-warning text: a
// responseStatus other than 200, or a translatedText starting with
// "MYMEMORY WARNING", is a failure, never a translation.
// Quota (https://mymemory.translated.net/doc/usagelimits.php, checked
// 2026-10-28): anonymous use is 5000 chars/day; providing a valid email
// via the 'de' parameter raises it to 50000 chars/day. The email comes
// only from the MYMEMORY_EMAIL env var — never hard-coded here. When the
// var is unset, no 'de' parameter is sent and behaviour is unchanged.
const MYMEMORY_EMAIL = (process.env.MYMEMORY_EMAIL || '').trim();
async function myMemoryTranslateBatch(texts, target = 'my') {
  // Bounded concurrency (6 parallel): MyMemory calls are network-bound, so
  // parallel requests cut translation time sharply for many lines, while the
  // CPU-bound Whisper path is deliberately left single-process. Order is
  // preserved via the index. Failure semantics are unchanged: if ANY line
  // fails (non-200, empty, or MYMEMORY WARNING quota text) the whole batch
  // throws, and the caller falls through to the NLLB offline path exactly as
  // before — no line is ever dropped or guessed.
  const out = new Array(texts.length);
  const CONC = 6;
  async function translateOne(i) {
    const t = texts[i];
    const params = { q: t, langpair: `${/[\u4e00-\u9fff]/.test(t) ? 'zh' : 'en'}|${target}` };
    if (MYMEMORY_EMAIL) params.de = MYMEMORY_EMAIL;
    const url = 'https://api.mymemory.translated.net/get?' + new URLSearchParams(params).toString();
    const r = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    const body = await r.text();
    let j; try { j = JSON.parse(body); } catch { throw new Error(`MyMemory returned unparseable output (HTTP ${r.status}): ${body.slice(0, 200)}`); }
    const txt = j.responseData?.translatedText || '';
    if (j.responseStatus !== 200 || !txt || txt.startsWith('MYMEMORY WARNING')) throw new Error(`MyMemory HTTP ${j.responseStatus}: ${(j.responseDetails || body).slice(0, 200)}`);
    out[i] = txt;
  }
  for (let s = 0; s < texts.length; s += CONC) {
    const chunk = [];
    for (let i = s; i < Math.min(s + CONC, texts.length); i++) chunk.push(translateOne(i));
    await Promise.all(chunk);
  }
  return out;
}
// Offline NLLB-200 translation via CTranslate2 (no key, no network at run
// time, no torch needed) — only if ctranslate2 + transformers are installed
// AND the JustFrederik ct2-int8 model is cached (see nllb_ct2_translate.py).
async function nllbTranslateBatch(texts) {
  const py = fs.existsSync(WHISPER_PYTHON) ? WHISPER_PYTHON : 'python3';
  const { out, err } = await new Promise((resolve, reject) => {
    const p = spawn(py, [path.join(__dirname, 'nllb_ct2_translate.py')]);
    let o = '', e = '';
    p.stdout.on('data', d => o += d); p.stderr.on('data', d => e += d);
    p.on('error', reject);
    p.on('close', code => code === 0 ? resolve({ out: o, err: e }) : reject(new Error(e.slice(-500) || `nllb exit ${code}`)));
    p.stdin.end(JSON.stringify(texts));
  });
  const parsed = JSON.parse(out.trim().split('\n').pop());
  if (!Array.isArray(parsed) || parsed.length !== texts.length) throw new Error('NLLB returned the wrong number of translations.');
  if (parsed.some(t => !t || !t.trim())) throw new Error('NLLB returned an empty translation for one or more lines.');
  return parsed;
}
// Offline Argos Translate (no key, no network) — only if the
// argostranslate package AND an en->my package are installed on this server.
// NOTE: as of 2026-10-26 no en->my Argos package is known to exist, so this
// path is kept only as a documented dead end; NLLB above is the offline path.
async function argosTranslateBatch(texts) {
  const py = fs.existsSync(WHISPER_PYTHON) ? WHISPER_PYTHON : 'python3';
  const script = `import sys, json, argos_translate
from argos_translate import translate as _t
installed = _t.get_installed_languages()
src = next((l for l in installed if l.code == 'en'), None)
dst = next((l for l in installed if l.code == 'my'), None)
if not src or not dst: raise SystemExit('ARGOS_NO_MY_PACKAGE')
tr = src.get_translation(dst)
print(json.dumps([tr(t) for t in json.load(sys.stdin)], ensure_ascii=False))`;
  const { out, err } = await new Promise((resolve, reject) => {
    const p = spawn(py, ['-c', script]);
    let o = '', e = '';
    p.stdout.on('data', d => o += d); p.stderr.on('data', d => e += d);
    p.on('error', reject);
    p.on('close', code => code === 0 ? resolve({ out: o, err: e }) : reject(new Error(e.slice(-500) || `argos exit ${code}`)));
    p.stdin.end(JSON.stringify(texts));
  });
  const parsed = JSON.parse(out.trim().split('\n').pop());
  if (!Array.isArray(parsed) || parsed.length !== texts.length) throw new Error('Argos returned the wrong number of translations.');
  return parsed;
}
// Batched LLM translation: ALL lines in ONE call (fastest path). The model must
// return one numbered translation per input line, in order. A count mismatch
// throws so the caller falls through -- lines are never misaligned or invented.
function buildBatchPrompt(texts, sourceLang) {
  const numbered = texts.map((t, i) => (i + 1) + '. ' + t).join('\n');
  const fromPart = (sourceLang && sourceLang !== 'auto') ? ('from ' + (SOURCE_LANG_NAMES[sourceLang] || sourceLang) + ' ') : '';
  return 'Translate each numbered line ' + fromPart + 'into natural, conversational Burmese (Myanmar script) suitable for subtitles/dubbing. Burmese word order: the noun comes BEFORE the number+classifier — write မြင်းနှစ်ကောင် and လူဆယ့်နှစ်ဦး, NEVER the Chinese order နှစ်ကောင်မြင်း or ဆယ့်နှစ်ဦးလူ. Return ONLY the translations, one per line, in the same order, each prefixed with its number and a period (e.g. "1. ..."). Do not add explanations, do not merge or drop lines, do not renumber.\n' + numbered;
}
function parseBatchResponse(text, count) {
  if (!text || !text.trim()) throw new Error('Empty batch translation response.');
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const numbered = new Array(count);
  let numberedCount = 0;
  for (const l of lines) {
    const m = l.match(/^(\d+)[.)]\s*(.*)$/);
    if (m) {
      const idx = parseInt(m[1], 10) - 1;
      if (idx >= 0 && idx < count && numbered[idx] === undefined) { numbered[idx] = (m[2] || '').trim(); numberedCount++; }
    }
  }
  if (numberedCount === count && numbered.every(t => t)) return numbered;
  if (lines.length === count) return lines;
  throw new Error('Batch translation returned the wrong number of lines.');
}
async function groqTranslateBatch(texts, sourceLang) {
  const key = process.env.GROQ_API_KEY;
  if (!key) throw new Error('GROQ_API_KEY not configured.');
  // Default model: cheapest self-serve Groq chat model (Llama 3.3/3.1 are
  // Enterprise-only since Aug 2026 and error on free keys). Override with
  // GROQ_TRANSLATE_MODEL if Groq changes its lineup again.
  const model = process.env.GROQ_TRANSLATE_MODEL || 'openai/gpt-oss-20b';
  const res = await fetch('https://api.groq.com/openai/v1/chat/completions', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key }, body: JSON.stringify({ model, temperature: 0.2, max_completion_tokens: 16384, messages: [{ role: 'user', content: buildBatchPrompt(texts, sourceLang) }] }) });
  const body = await res.text();
  if (!res.ok) throw new Error(`Groq HTTP ${res.status}: ${body.slice(0, 300)}`);
  let j; try { j = JSON.parse(body); } catch { throw new Error('Groq returned unparseable output.'); }
  const content = (j.choices?.[0]?.message?.content || '').trim();
  return parseBatchResponse(content, texts.length);
}
async function geminiTranslateBatch(texts, sourceLang) {
  const key = process.env.GEMINI_API_KEY;
  if (!key) throw new Error('GEMINI_API_KEY not configured.');
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_TRANSCRIBE_MODEL}:generateContent?key=${key}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contents: [{ parts: [{ text: buildBatchPrompt(texts, sourceLang) }] }], generationConfig: { temperature: 0.2, maxOutputTokens: 16384 } }) });
  const body = await res.text();
  if (!res.ok) throw new Error(`Gemini HTTP ${res.status}: ${body.slice(0, 300)}`);
  let j; try { j = JSON.parse(body); } catch { throw new Error('Gemini returned unparseable output.'); }
  const content = (j.candidates?.[0]?.content?.parts?.map(x => x.text).join('') || '').trim();
  return parseBatchResponse(content, texts.length);
}
async function withRetry(fn) { let last; for (let a = 0; a < 2; a++) { try { return await fn(); } catch (e) { last = e; if (a === 0) await new Promise(r => setTimeout(r, 5000)); } } throw last; }
async function translateLinesWithGoogleOrFallback(lines, sourceLang) {
  // lines: [{original}] -> {translations, path, error}
  // Order: Gemini batched first when a Gemini key is set (accuracy first),
  // else Groq batched (fastest) -> Gemini batched ->
  // Google batch -> MyMemory parallel -> NLLB offline -> Argos offline.
  // Every step is labelled in `path`; a failure never invents a translation.
  const originals = lines.map(l => l.original);
  const attempts = [];
  if (process.env.GEMINI_API_KEY) {
    try {
      const translations = await withRetry(() => geminiTranslateBatch(originals, sourceLang));
      return { translations, path: 'gemini-batch', googleLog: 'Translated in one Gemini batch call.', error: null };
    } catch (me) { attempts.push(`Gemini batch: ${me.message}`); }
  }
  try {
    const translations = await withRetry(() => groqTranslateBatch(originals, sourceLang));
    return { translations, path: 'groq-batch', googleLog: 'Translated in one Groq batch call (fastest path).', error: null };
  } catch (ge) { attempts.push(`Groq batch: ${ge.message}`); }
  try {
    const translations = await withRetry(() => geminiTranslateBatch(originals, sourceLang));
    return { translations, path: 'gemini-batch', googleLog: 'Translated in one Gemini batch call.', error: null };
  } catch (me) { attempts.push(`Gemini batch: ${me.message}`); }
  try {
    const translations = await googleTranslateBatch(originals, 'my', (sourceLang && sourceLang !== 'auto') ? sourceLang : 'auto');
    return { translations, path: 'google', googleLog: 'Translated via Google batch.', error: null };
  } catch (ge) { attempts.push(`Google: ${ge.message}`); }
  try {
    const translations = await myMemoryTranslateBatch(originals, 'my');
    return { translations, path: 'mymemory', googleLog: 'Translated via MyMemory free API.', error: `Groq + Gemini + Google failed: ${attempts.join(' ')} — MyMemory fallback used instead.` };
  } catch (me) { attempts.push(`MyMemory: ${me.message}`); }
  try {
    const translations = await nllbTranslateBatch(originals);
    return { translations, path: 'nllb-offline', googleLog: 'Translated offline with NLLB-200 en->mya_Mymr on this server (no key, no network).', error: `Groq + Gemini + Google + MyMemory failed: ${attempts.join(' ')} — NLLB offline fallback used instead.` };
  } catch (ne) { attempts.push('NLLB offline: not installed on this server.'); }
  try {
    const translations = await argosTranslateBatch(originals);
    return { translations, path: 'argos-offline', googleLog: 'Translated offline with Argos Translate en->my on this server (no key, no network).', error: `Groq + Gemini + Google + MyMemory + NLLB failed: ${attempts.join(' ')} — Argos offline fallback used instead.` };
  } catch (ae) { attempts.push('Argos offline: not installed on this server.'); }
  return { translations: null, path: 'failed', googleLog: null, error: `All translation paths failed (${attempts.join(' ')}), so no translation was invented.` };
}

